export interface FeedItem {
  id: number;
  title: string;
  body: string;
}

export interface FeedResponse {
  items: FeedItem[];
  nextCursor: number | null;
}

const ALL_ITEMS: FeedItem[] = Array.from({ length: 25 }, (_, idx) => ({
  id: idx + 1,
  title: `Feed Item #${idx + 1}`,
  body: `This is the detailed content for feed item number ${idx + 1}. It contains some placeholder text describing the item.`,
}));

export const fetchFeedData = async (cursor: number = 0, limit: number = 5): Promise<FeedResponse> => {
  // Simulate network latency of 500ms
  await new Promise((resolve) => setTimeout(resolve, 500));

  const startIndex = cursor;
  const endIndex = startIndex + limit;
  const items = ALL_ITEMS.slice(startIndex, endIndex);
  const nextCursor = endIndex < ALL_ITEMS.length ? endIndex : null;

  return {
    items,
    nextCursor,
  };
};

import { useInfiniteQuery } from '@tanstack/react-query'
import { fetchFeedData } from './api'
import './App.css'

function App() {
  const {
    data,
    error,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    status,
  } = useInfiniteQuery({
    queryKey: ['feed'],
    queryFn: ({ pageParam }) => fetchFeedData(pageParam),
    initialPageParam: 0,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
  })

  return (
    <div className="feed-container">
      <header className="feed-header">
        <h1>TanStack Query Infinite Scrolling Feed</h1>
        <p>Demonstrating pagination and server state management with React and TanStack Query.</p>
      </header>

      <main className="feed-main">
        {status === 'pending' ? (
          <div className="status-message">Loading initial feed...</div>
        ) : status === 'error' ? (
          <div className="status-message error">
            Error loading feed: {(error as Error).message}
          </div>
        ) : (
          <>
            <ul className="feed-list">
              {data.pages.map((page, pageIdx) => (
                <div key={pageIdx} className="page-group">
                  {page.items.map((item) => (
                    <li key={item.id} className="feed-item">
                      <span className="item-id">#{item.id}</span>
                      <h3 className="item-title">{item.title}</h3>
                      <p className="item-body">{item.body}</p>
                    </li>
                  ))}
                </div>
              ))}
            </ul>

            <div className="feed-actions">
              {hasNextPage ? (
                <button
                  type="button"
                  className="load-more-btn"
                  onClick={() => fetchNextPage()}
                  disabled={isFetchingNextPage}
                >
                  {isFetchingNextPage ? 'Loading...' : 'Load More'}
                </button>
              ) : (
                <p className="no-more-items">No more items to load</p>
              )}
            </div>
          </>
        )}
      </main>
    </div>
  )
}

export default App

